{"research_date": "2026-09-10", "pairs": [{"pair_id": "conflict_92b0a38ca066cd34658a506b", "claim_ids": ["claim_60bd21591628a7a8e4991de3", "claim_f284da24e78e558e7c60a0d2"], "query_ids": ["q_456"], "claims": [{"claim_id": "claim_60bd21591628a7a8e4991de3", "quote": "Commercial vehicles, such as sedans, sport utility vehicles, crossover utility vehicles, minivans, cargo vans and light trucks, provided for in heading 9903.94.01, HTSUS, are subject to the Section 232 duties pursuant to the Proclamation.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232 duties", "affected_product": "Commercial vehicles, such as sedans, sport utility vehicles, crossover utility vehicles, minivans, cargo vans and light trucks", "hts_code": "9903.94.01, HTSUS"}}, {"claim_id": "claim_f284da24e78e558e7c60a0d2", "quote": "Light trucks classified in subheadings 8704.21.01, 8704.31.01, 8704.41.00, 8704.51.00, and 8704.60.00 are subject to the duties.", "url": "https://www.cbp.gov/trade/programs-administration/entry-summary/section-232-additional-faqs-autos", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"affected_product": "Light trucks", "hts_code": "8704.21.01, 8704.31.01, 8704.41.00, 8704.51.00, and 8704.60.00", "reported_policy_status": "subject to the duties"}}]}, {"pair_id": "conflict_a65477ecf649cf6525ec4d8e", "claim_ids": ["claim_265ea4e91b1b11f18e3c94a0", "claim_6376e52af9c3f7b865f74258"], "query_ids": ["q_458"], "claims": [{"claim_id": "claim_265ea4e91b1b11f18e3c94a0", "quote": "Based upon the facts provided, we find that the processing and assembly operations performed in the United States constitute a substantial transformation of the foreign-origin components. Therefore, the country of origin of the stereoscopic display models is the United States for purposes of U.S. Government procurement.", "url": "https://rulings.cbp.gov/ruling/H015324", "kind": "search_snippet", "publisher_type": "official_trade_authority", "fields": {"country_of_origin": "United States"}}, {"claim_id": "claim_6376e52af9c3f7b865f74258", "quote": "In ruling HQ H332752, CBP concluded that the country of origin of the devices is Taiwan because the assembly of the main PCBA in Taiwan results in a substantial transformation.", "url": "https://www.strtrade.com/trade-news-resources/str-trade-report/trade-report/june/cbp-rules-on-origin-of-led-display-panels", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "CBP", "country_of_origin": "Taiwan"}}]}, {"pair_id": "conflict_b0ef5c2525a4468c9a93ac01", "claim_ids": ["claim_028b7f1105bf240bab714fc4", "claim_eaa9e638c497c4b96a16ffbf"], "query_ids": ["q_459"], "claims": [{"claim_id": "claim_028b7f1105bf240bab714fc4", "quote": "The US and South Korea agreed on tariffs of 15% for vehicle imports and automotive parts imports in late July, replacing the previously threatened 25% rate. This came into effect on August 1, but as of early September, the agreement remains provisional and has not been formally finalised.", "url": "https://www.automotivelogistics.media/supply-chain/tariff-analysis-deep-dive-the-most-important-changes-for-the-auto-industry/663875", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "tariffs of 15%", "affected_product": "vehicle imports and automotive parts imports", "duty_rate": "15%", "effective_date": "August 1"}}, {"claim_id": "claim_eaa9e638c497c4b96a16ffbf", "quote": "In August, the US administration extended the scope of the 50% import tariffs for steel and aluminium goods, adding more than 400 additional items to the levy, including car parts such as chassis components, axles, steel wiring, brackets and mounts, and parts of heavy vehicles.", "url": "https://www.automotivelogistics.media/supply-chain/tariff-analysis-deep-dive-the-most-important-changes-for-the-auto-industry/663875", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "50% import tariffs for steel and aluminium goods", "affected_product": "car parts such as chassis components, axles, steel wiring, brackets and mounts, and parts of heavy vehicles", "duty_rate": "50%", "effective_date": "August"}}]}, {"pair_id": "conflict_9b1377faccbd989d1725a60d", "claim_ids": ["claim_38d8e71ff2cc691b45665250", "claim_c0353fc95beeb129ae1a94bd"], "query_ids": ["q_461"], "claims": [{"claim_id": "claim_38d8e71ff2cc691b45665250", "quote": "Retailers scrambling to stock up ahead of anticipated stiff tariffs on imports boosted the Port of Savannah, one of the top U.S. container ports, to its second-busiest year ever, Georgia officials said Tuesday.", "url": "https://finance.yahoo.com/news/cargo-surge-amid-tariff-turmoil-144757802.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Port of Savannah", "tariff_program": "anticipated stiff tariffs on imports", "duty_rate": "stiff"}}, {"claim_id": "claim_c0353fc95beeb129ae1a94bd", "quote": "Retailers scrambling to stock up ahead of anticipated stiff tariffs on imports boosted the Port of Savannah, one of the top U.S. container ports, to its second-busiest year ever, Georgia officials said Tuesday.", "url": "https://www.wabe.org/cargo-surge-amid-tariff-turmoil-drives-the-port-of-savannah-to-its-2nd-busiest-year", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Port of Savannah", "tariff_program": "anticipated stiff tariffs on imports"}}]}, {"pair_id": "conflict_a22b3661219468d15d6ff58f", "claim_ids": ["claim_79040501f75d79e2f0ec0e86", "claim_8d67186055b32a2f6d526b4b"], "query_ids": ["q_461"], "claims": [{"claim_id": "claim_79040501f75d79e2f0ec0e86", "quote": "The growth was caused in part by a surge in cargo since President Donald Trump returned to office in January, promising heavy tariffs on China and other U.S. trading partners.", "url": "https://www.wabe.org/cargo-surge-amid-tariff-turmoil-drives-the-port-of-savannah-to-its-2nd-busiest-year", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "President Donald Trump", "tariff_program": "heavy tariffs on China and other U.S. trading partners"}}, {"claim_id": "claim_8d67186055b32a2f6d526b4b", "quote": "The growth was caused in part by a surge in cargo since President Donald Trump returned to office in January promising heavy tariffs on China and other U.S. trading partners.", "url": "https://finance.yahoo.com/news/cargo-surge-amid-tariff-turmoil-144757802.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"announcement_date": "January"}}]}, {"pair_id": "conflict_9ce5c36d1c519a273ec0dd0b", "claim_ids": ["claim_6926953d440c82d66bc1862d", "claim_d027b0cd4f18e7ffb0b0ff8a"], "query_ids": ["q_461"], "claims": [{"claim_id": "claim_6926953d440c82d66bc1862d", "quote": "A 90-day pause the Republican president placed on new tariffs announced in April gave American retailers and manufacturers a window to build up inventories ahead of new price hikes.", "url": "https://finance.yahoo.com/news/cargo-surge-amid-tariff-turmoil-144757802.html", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "new tariffs", "expiration_date": "90-day pause", "reported_policy_status": "announced in April"}}, {"claim_id": "claim_d027b0cd4f18e7ffb0b0ff8a", "quote": "A 90-day pause the Republican president placed on new tariffs announced in April gave American retailers and manufacturers a window to build up inventories ahead of new price hikes.", "url": "https://www.wabe.org/cargo-surge-amid-tariff-turmoil-drives-the-port-of-savannah-to-its-2nd-busiest-year", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "Republican president", "tariff_program": "new tariffs announced in April"}}]}, {"pair_id": "conflict_b71be45caa72b624a3e46d64", "claim_ids": ["claim_1b7b3a82e37059091e7a528e", "claim_9507b2ed667bed6966dbb4dd"], "query_ids": ["q_462"], "claims": [{"claim_id": "claim_1b7b3a82e37059091e7a528e", "quote": "Right now, the tariffs on steel and aluminum imports into the US have doubled to 50% for all countries except the UK. The tariffs, which took effect on June 4, include derivative products that contain a proportion of those metals.", "url": "https://www.bcg.com/publications/2025/june-2025-update-impact-us-tariffs-50-percent-on-steel-aluminum", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 measures", "duty_rate": "50%", "effective_date": "June 4"}}, {"claim_id": "claim_9507b2ed667bed6966dbb4dd", "quote": "Yesterday, President Donald J. Trump signed proclamations to close existing loopholes and exemptions to restore a true 25% tariff on steel and elevate the tariff to 25% on aluminum.", "url": "https://www.whitehouse.gov/fact-sheets/2025/02/fact-sheet-president-donald-j-trump-restores-section-232-tariffs", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232", "duty_rate": "25%", "effective_date": "Yesterday", "reported_policy_status": "signed proclamations"}}]}, {"pair_id": "conflict_c7efb7af70de3e7529497554", "claim_ids": ["claim_1b7b3a82e37059091e7a528e", "claim_fea885ff3d312f68ef00ca9f"], "query_ids": ["q_462"], "claims": [{"claim_id": "claim_1b7b3a82e37059091e7a528e", "quote": "Right now, the tariffs on steel and aluminum imports into the US have doubled to 50% for all countries except the UK. The tariffs, which took effect on June 4, include derivative products that contain a proportion of those metals.", "url": "https://www.bcg.com/publications/2025/june-2025-update-impact-us-tariffs-50-percent-on-steel-aluminum", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "Section 232 measures", "duty_rate": "50%", "effective_date": "June 4"}}, {"claim_id": "claim_fea885ff3d312f68ef00ca9f", "quote": "In March 2018, President Trump invoked authority under Section 232 of the Trade Expansion Act of 1962 (19 U.S.C. § 1862) to impose 25% tariffs on steel imports and 10% tariffs on aluminum.", "url": "https://www.whitehouse.gov/fact-sheets/2025/02/fact-sheet-president-donald-j-trump-restores-section-232-tariffs", "kind": "full_document", "publisher_type": "official_trade_authority", "fields": {"tariff_program": "Section 232", "duty_rate": "25%", "announcement_date": "March 2018"}}]}, {"pair_id": "conflict_4b01cb37cfdc872bef3ca9ad", "claim_ids": ["claim_1fb197bc421567d4b13ab2d6", "claim_f5902beba796c5a6824fed47"], "query_ids": ["q_463"], "claims": [{"claim_id": "claim_1fb197bc421567d4b13ab2d6", "quote": "India was taking off, and it was going very fast, but now they still have 50% tariffs on Indian products.", "url": "https://augustabusinessdaily.com/part-2-impact-of-tariffs-on-imports-sales-and-the-georgia-ports", "kind": "full_document", "publisher_type": "secondary_or_unverified_publisher", "fields": {"country_of_origin": "India", "duty_rate": "50%"}}, {"claim_id": "claim_f5902beba796c5a6824fed47", "quote": "AS A RESULT OF THE 145 PERCENT TARIFFS ON CHINESE IMPORTS - PRESIDENT TRUMP ANNOUNCED BACK IN APRIL", "url": "https://www.youtube.com/watch?v=GaFiWuGhJTo", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"tariff_program": "145 PERCENT TARIFFS ON CHINESE IMPORTS", "announcement_date": "APRIL"}}]}, {"pair_id": "conflict_c4224c60ab6d7b1efa4817f3", "claim_ids": ["claim_7fb184ced7d27a86d470ea56", "claim_fe023bb827ed81215c2c7dbd"], "query_ids": ["q_464"], "claims": [{"claim_id": "claim_7fb184ced7d27a86d470ea56", "quote": "Georgia's nearby Port of Brunswick saw automobile shipments drop 2.2% as it moved 811,042 cars and trucks in fiscal 2025.", "url": "https://apnews.com/article/georgia-port-of-savannah-statistics-tariffs-3b7ae80b790d8de9fde4e297ca7d00f9", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"facility": "Port of Brunswick", "duty_rate": "2.2%"}}, {"claim_id": "claim_fe023bb827ed81215c2c7dbd", "quote": "GPA saw a 7.5% decline in 2025 volume at the Port of Brunswick, its Roll-On/Roll-Off port for autos and heavy machinery. The drop in volume was driven by tariffs that led to some manufacturers pausing shipments", "url": "https://www.savannahnow.com/story/news/local/2026/01/28/georgia-ports-authority-weathers-year-of-tariffs-with-strong-performance/88382339007", "kind": "search_snippet", "publisher_type": "secondary_or_unverified_publisher", "fields": {"company": "GPA", "facility": "Port of Brunswick", "tariff_program": "tariffs"}}]}]}

